mapper.update:
update user_post_favorite
set status = #{status}
where id = #{id}

mapper.select:
SELECT * FROM user_post_favorite
WHERE user_id = #{userId} AND post_id = #{postId}
limit 1;

mapper.delete:
update user_post_favorite
set status = 'C'
WHERE user_id = #{userId} AND post_id = #{postId}

mapper.select:
SELECT post_id AS id, COUNT(1) AS `count` FROM user_post_favorite WHERE status = 'A' and post_id IN
#{pid}
GROUP BY post_id
